"""The `screen_judge` cell of talky (#1279): the form the screen takes in a turn.

Off as shipped (`enabled` "0"): it hears the keeper's turn and sends nothing. On ("1")
it orders the curator's view of the turn for the target the param `view_target` names
(`view_ask`, answered on `in_view`; D58 GH #1480, the composite sets the name, the cell
has none built in; the turn's text rides out and back on the hop), folds it into the
facts it always gave (the route's view helpers, the leaves `view_sources` names), asks
`./screen_model` ONE structured question and sends ONE rim message `verdict` with
`{stamp: {turn_id, audience_set, screen_form}}` -- the second stamp of the turn, for
the presenter's `in_verdict` only (never on the rim's `stamp`). The
route stamp never waits for it: it leaves without `screen_form`, the form follows.
An error, a refusal or an answer that is no form sends nothing, and the presenter
stays at its standard. A turn without a round sends nothing either (fail-closed, as
the route stamp's rim copy).

Lanes, no state: `in_turn`, `in_view`, `in_verdict` (the model's answer).
"""

import json
import sys

# The four forms. Fixed: `./screen_model` answers with one of them
# through its json_schema, so a form is never a product word.
# #1417: each form is told by what the person ASKS FOR. Measured in live-2 T5 round 2b:
# form 0.80 under the 0.85 bar, while the set's json_schema `description` of
# `screen_form` told the forms by the request and these lines told `referring` by the
# result ("a list or a plan too long to read aloud") and called anything personal
# `none` -- two texts in one call that contradicted each other.
FORMS = {
    "active": "the person asks to see something or to be shown it (show me ...): the screen is the answer and takes the focus",
    "accompanying": "the person asks about the world (the weather, a price, a place, a timer): the voice answers by itself and the screen adds a picture beside it",
    "referring": "the person asks about entries of their own (their appointments, their free time, their tasks, their lists): the voice says the gist or the next one and the screen holds them all",
    "none": "the person asks for nothing to look up or keep: talk that wants something felt, told or shared",
}
BUDGET_CAP = 4000
BUDGET_DEFAULT = 1500


def emission(route, body, **header):
    head = {"route": route}
    head.update(header)
    out = {"header": head, "messages": []}
    out.update(body)
    return out


def number(params, key, default):
    v = params.get(key)
    if isinstance(v, bool):
        return default
    try:
        return float(v)
    except (TypeError, ValueError):
        return default


def text_of(body):
    said = []
    for m in body.get("messages") or []:
        if isinstance(m, dict) and m.get("type", "text") == "text" \
                and m.get("origin", "user") != "assistant" \
                and isinstance(m.get("text"), str):
            said.append(m["text"])
    return " ".join(s for s in said if s.strip()).strip()


def has_round(value):
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except ValueError:
            return False
    return isinstance(value, list)


def view_target(params):
    """D58 GH #1480: the target this cell orders its view for -- the param `view_target`,
    no built-in name (R-58-15); "" orders a view without a target."""
    target = params.get("view_target")
    return target.strip() if isinstance(target, str) else ""


def leaf_text(tree, *path):
    """The text of the leaf at `path` of a view's system tree, "" when there is none."""
    node = tree
    for name in path:
        node = node.get(name) if isinstance(node, dict) and name else None
    text = node.get("text") if isinstance(node, dict) else None
    return text if isinstance(text, str) else ""


def leaf_data(tree, *path):
    """A structured leaf read back from its JSON text (the curator keeps a structured
    contribution as its JSON text, unread); None when there is none or it is no JSON."""
    text = leaf_text(tree, *path)
    try:
        return json.loads(text) if text else None
    except ValueError:
        return None


def frame_facts(text):
    """The leaf `frame` of a view: one `<name>: <value>` fact per line (now, weekday,
    timezone, place; OR-d58-2.judge.8)."""
    facts = {}
    for line in text.split("\n"):
        name, sep, value = line.partition(":")
        if sep:
            facts[name.strip()] = value[1:] if value.startswith(" ") else value
    return facts


def kept_topics(value):
    """The screen topics of the screen leaf in the form the curator kept them before D58
    (`{name, purpose, candidates?: [{key, describe}]}`, names and keys stripped, each
    name once, an absent purpose or describe ""): the curator no longer reads the value,
    and the decide text and questions stay the bytes they were."""
    out, seen = [], set()
    for t in value if isinstance(value, list) else []:
        name = str(t.get("name") or "").strip() if isinstance(t, dict) else ""
        if not name or name in seen:
            continue
        seen.add(name)
        topic = {"name": name, "purpose": str(t.get("purpose") or "")}
        cands = t.get("candidates")
        if isinstance(cands, list):
            topic["candidates"] = [
                {"key": str(c.get("key") or "").strip(), "describe": str(c.get("describe") or "")}
                for c in cands if isinstance(c, dict) and str(c.get("key") or "").strip()]
        out.append(topic)
    return out


def view_context(body, params, hop=None):
    """D58 GH #1480: the judge context out of a view -- `messages` as the turns, the
    leaves `topic` and `frame`, and the leaves of the target's family that the param
    `view_sources` names (`screen`: the screen topics, `hints`: the person's how-
    questions); None for a view without a system tree (a view without a target).
    The screen is held whenever the view is (no screen state reaches the curator, so
    the decide text says "- nothing" as it always did).

    A refused or degraded view (`hop.refused`, `hop.degraded`) is no judge context
    (review I1): without the leaf `frame` (the refusal at the curator's door) it gives
    None, the turn alone, as the turns ask without a package did; with it the moment
    alone, as the package of now and place without turns, topic or screen did -- the
    text stays the bytes it was in both places."""
    system = body.get("system")
    if not isinstance(system, dict):
        return None
    hop = hop if isinstance(hop, dict) else {}
    if hop.get("refused") or hop.get("degraded"):
        if not leaf_text(system, "frame"):
            return None
        body, system = {}, {"frame": system["frame"]}
    sources = params.get("view_sources") if isinstance(params.get("view_sources"), dict) else {}
    target = view_target(params)
    turns = [{"role": str(m.get("origin") or ""), "text": m.get("text")}
             for m in body.get("messages") or []
             if isinstance(m, dict) and m.get("type", "text") == "text"]
    frame = frame_facts(leaf_text(system, "frame"))
    hints = leaf_data(system, target, str(sources.get("hints") or ""))
    return {"turns": turns, "topic": leaf_text(system, "topic"),
            "hints": hints if isinstance(hints, list) else [],
            "screen": {"topics": kept_topics(
                leaf_data(system, target, str(sources.get("screen") or "")))},
            "now": {k: frame.get(n, "") for k, n in
                    (("iso", "now"), ("weekday", "weekday"), ("timezone", "timezone"))},
            "place": frame.get("place", "")}


def judge_lines(judge):
    """The judge context as facts, in the route cell's wording."""
    parts = []
    said = []
    for t in judge.get("turns") if isinstance(judge.get("turns"), list) else []:
        if isinstance(t, dict) and str(t.get("text") or "").strip():
            who = "companion" if t.get("role") == "assistant" else "person"
            said.append("- %s: %s" % (who, str(t["text"]).strip()))
    if said:
        parts.append("Earlier in this conversation (oldest first):\n" + "\n".join(said))
    topic = judge.get("topic")
    if isinstance(topic, str) and topic.strip():
        parts.append("The conversation is about: " + topic.strip())
    screen = judge.get("screen") if isinstance(judge.get("screen"), dict) else {}
    topics = []
    for t in screen.get("topics") if isinstance(screen.get("topics"), list) else []:
        if isinstance(t, dict) and isinstance(t.get("name"), str) and t["name"]:
            line = "- %s: %s" % (t["name"], str(t.get("purpose") or ""))
            cands = [c for c in t.get("candidates") or [] if isinstance(c, dict)
                     and isinstance(c.get("key"), str)]
            if cands:
                line += ". Blocks: " + "; ".join(
                    "%s (%s)" % (c["key"], str(c.get("describe") or "")) for c in cands)
            topics.append(line)
    if topics:
        parts.append("Screen topics:\n" + "\n".join(topics))
    if isinstance(judge.get("screen"), dict):
        # D58 GH #1480: no screen state reaches the curator (master's history answered
        # `state: []` on every read), so the line names nothing, the bytes of before.
        parts.append("On the screen right now:\n- nothing")
    now = judge.get("now") if isinstance(judge.get("now"), dict) else {}
    if isinstance(now.get("iso"), str) and now["iso"]:
        when = ", ".join(str(now[k]) for k in ("weekday", "iso")
                         if isinstance(now.get(k), str) and now[k])
        tz = now.get("timezone")
        parts.append("Now: %s%s" % (when, " (%s)" % tz if isinstance(tz, str) and tz else ""))
    place = judge.get("place")
    if isinstance(place, str) and place.strip():
        parts.append("Place: " + place.strip())
    return parts


INSTRUCTIONS = (
    "You decide at once how the screen beside a spoken answer takes part in the answer to "
    "one request. Each form is told by what the person asks for, never by how long the "
    "answer is. Answer only with the JSON object {\"screen_form\": <form>}, the form one of:\n"
    + "\n".join("- %s: %s" % kv for kv in FORMS.items()) + "\n"
    "Small talk, greetings, feelings, thanks and stories: none. A short "
    "follow-up means what the earlier conversation and the screen make of it. When no screen "
    "topic fits what the person wants: none. Never guess.")


def model_call(judge, text, turn_id):
    parts = judge_lines(judge if isinstance(judge, dict) else {})
    state = "%s\n\nThe request now:\n%s" % ("\n\n".join(parts), text) if parts else text
    return [emission("screen_model", {
        "system": {"instructions": {"text": INSTRUCTIONS}},
        "messages": [{"origin": "user", "type": "text", "text": state}]}, turn_id=turn_id)]


def form_of(body, hop):
    if str(hop.get("finish_reason") or "") != "stop" or hop.get("error_code"):
        return None
    text = next((m.get("text") for m in body.get("messages") or []
                 if isinstance(m, dict) and m.get("type", "text") == "text"
                 and isinstance(m.get("text"), str) and m["text"].strip()), "")
    try:
        answer = json.loads(text)
    except ValueError:
        return None
    form = answer.get("screen_form") if isinstance(answer, dict) else None
    return form if form in FORMS else None


def switch_on(v):
    """One switch (#1370): JSON true, "1", "true" or "on" is on, anything else
    off -- the rule of the presenter's `knob()`. A set writes its switches as
    JSON true (soul2me 0.45 `04-assistant.json`), and `str(True)` is "True":
    a read `== "1"` kept them off without a word."""
    return str(v).strip().lower() in ("1", "true", "on")


def handle(doc):
    body = doc.get("body") or {}
    params = doc.get("params") or {}
    header = (doc.get("envelope") or {}).get("header") or {}
    hop = header.get("hop") or {}
    ctx = header.get("context") or {}
    if not switch_on(params.get("enabled")):
        return []
    route = str(hop.get("route") or "")
    turn_id = str(ctx.get("turn_id") or hop.get("turn_id") or "")
    if not turn_id:
        return []
    if route == "in_turn":
        text = text_of(body)
        if not text or not has_round(ctx.get("audience_set")):
            return []
        n = max(0, int(number(params, "context_turns", 4)))
        budget = int(number(params, "context_budget_tokens", BUDGET_DEFAULT))
        budget = min(budget if budget > 0 else BUDGET_DEFAULT, BUDGET_CAP)
        ask = {"turns": n, "budget_tokens": budget}
        if view_target(params):
            ask["target"] = view_target(params)
        return [emission("view_ask", {"view_ask": ask}, state=text, turn_id=turn_id)]
    if route == "in_view":
        text = str(hop.get("state") or "")
        if not text:
            return []
        return model_call(view_context(body, params, hop), text, turn_id)
    if route == "in_verdict":
        form = form_of(body, hop)
        if form is None or not has_round(ctx.get("audience_set")):
            return []
        return [emission("verdict", {"stamp": {"turn_id": turn_id,
                                               "audience_set": ctx.get("audience_set"),
                                               "screen_form": form}}, turn_id=turn_id)]
    return []


out = handle(json.load(sys.stdin))
sys.stdout.write(json.dumps(out[0] if len(out) == 1 else out))
